487	\section{Conditionally linear functions and distributions}
488	% Paper subsection label sec:cl kept for cross-reference fidelity.
489	\label{sec:cl}
490	
491	Conditionally linear functions specify the question distributions of the games considered in the following chapters in a form that can be ``introspected''. Intuitively, a conditionally linear function takes as input an element $x \in V = \F^n$ and applies linear maps $L_j$ sequentially to $x^{V_j}$, where $V_1, V_2, \dots$ is a sequence of complementary register subspaces such that both the linear map $L_j$ and the subspace $V_j$, for $j \ge 2$, may depend on the values taken by the previous linear maps $L_1(x^{V_1})$, $L_2(x^{V_2})$, and so on.
492	
493	Throughout this section $V$ denotes the linear space $\F^n$ for some integer $n \ge 0$, and all the distinguished subspaces of $V$ are register subspaces (Definition~\ref{def:register-subspace}). If $V_1, V_2, \dots, V_\ell$ are fixed subspaces of $V$ and $k \in \{1, 2, \dots, \ell\}$, we use the subscript range notation
494	\[
495		V_{<k} = \bigoplus_{j\,:\,1 \le j < k} V_j\,, \qquad V_{>k} = \bigoplus_{j\,:\,\ell \ge j > k} V_j\,,
496	\]
497	and $V_{\le k}$, $V_{\ge k}$ are understood to be $V_{<k+1}$ and $V_{>k-1}$, respectively. For a register subspace $V'$ of $V$, the symbol $x^{V'}$ denotes the projection of $x$ onto $V'$ parallel to the complementary register subspace (Definition~\ref{def:complementary}). Moreover, if $F \colon V' \to V'$ is a function and $x \in V$, we write $x^F$ for $F(x^{V'})$; for example, in the following definition $x^{L_1}$ is shorthand for $L_1(x^{V_1})$.
498	
499	\begin{definition}[Conditionally linear functions]\label{def:cl-func}
500		\uses{def:register-subspace, def:complementary}
501		Let $V$ be $\F^n$ for some $n \ge 0$. For all integers $\ell \ge 0$ the collection of \emph{$\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is defined inductively as follows.
502		\begin{enumerate}
503			\item There is a single $0$-level conditionally linear function, which is the $0$ function on $V$.
504			\item Let $\ell \ge 1$ and suppose the collection of $(\ell-1)$-level conditionally linear functions has been defined. The collection of $\ell$-level conditionally linear functions on $V$ consists of all functions $L$ on $V$ that can be expressed in the following form: there exist complementary register subspaces $V_1$ and $V_{>1}$ of $V$, a linear function $L_1$ on $V_1$, and, for all $v \in L_1(V_1)$, an $(\ell-1)$-level conditionally linear function $L_{>1,\,v}$ on $V_{>1}$, such that for all $x \in V$,
505			\[
506				L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})\,.
507			\]
508		\end{enumerate}
509	\end{definition}
510	
511	We abbreviate ``conditionally linear'' as \emph{CL}. Operationally, an $\ell$-level CL function first applies $L_1$ to $x^{V_1}$; conditioned on the value $x^{L_1}$ it selects a register subspace $V_2$ and a linear map $L_2$ and applies $L_2$ to $x^{V_2}$; and so on, finally outputting $\sum_{k=1}^{\ell} x^{L_k}$. Every $1$-level CL function is linear, and conversely every linear map on $V$ is a $1$-level CL function. Moreover, for every $\ell \ge 1$ the collection of $\ell$-level CL functions contains the collection of $(\ell-1)$-level CL functions.
512	
513	\begin{definition}[Conditionally linear distributions]\label{def:cl-dist}
514		\uses{def:cl-func}
515		Let $L, R \colon V \to V$ be conditionally linear functions. The \emph{conditionally linear distribution $\mu_{L,R}$ corresponding to $(L,R)$} is the distribution over pairs $(L(x), R(x)) \in V \times V$ for $x$ drawn uniformly at random from $V$.
516	\end{definition}
517	
518	Note that both players' questions are generated from the \emph{same} uniformly random seed $x$; this shared-seed structure is what the introspection technique exploits. The following lemma elucidates the structural properties of $\ell$-level CL functions. Recall that $x^{L_{<k}}$ and $x^{L_k}$ denote $L_{<k}(x)$ and $L_{k,\,u}(x^{V_{k,\,u}})$ where $u = L_{<k}(x)$.
519	
520	\begin{lemma}[Structure of conditionally linear functions]\label{lem:cl-kth}
521		\lean{MIPStarRE.QPBT.CLData, MIPStarRE.QPBT.isCondLinear_iff_nonempty_clData}
522		\leanok
523		\uses{def:cl-func, def:register-subspace}
524		Let $\ell \ge 1$ and $V = \F^n$ for some integer $n \ge 0$. A function $L \colon V \to V$ is an $\ell$-level CL function if and only if the following collection of functions and subspaces exists:
525		\begin{enumerate}
526			\item[(i)] for each $k \in \{1, 2, \dots, \ell\}$, a function $L_{\le k} \colon V \to V$, called the \emph{$k$-th marginal of $L$};
527			\item[(ii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a register subspace $V_{k,\,u}$ of $V$, called the \emph{$k$-th factor space with prefix $u$};
528			\item[(iii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a linear map $L_{k,\,u} \colon V_{k,\,u} \to V_{k,\,u}$, called the \emph{$k$-th linear map of $L$ with prefix $u$};
529		\end{enumerate}
530		such that the following conditions hold for all $k \in \{1, 2, \dots, \ell\}$:
531		\begin{enumerate}
532			\item $L_{\le k}$ is a $k$-level CL function on $V$;
533			\item $V = \bigoplus_{i=1}^{\ell} V_{i,\,x^{L_{<i}}}$ for all $x \in V$;
534			\item $L_{\le k}(x) = \sum_{i=1}^{k} x^{L_i}$ for all $x \in V$, where $L_i$ is shorthand notation for $L_{i,\,x^{L_{<i}}}$;
535			\item $L = L_{\le \ell}$.
536		\end{enumerate}
537		As in condition 3, we sometimes use $V_k$ and $L_k$ to denote $V_{k,\,u}$ and $L_{k,\,u}$ respectively, leaving the prefix $u$ implicit.
538		Index the decomposition levels by $0,\ldots,\ell-1$; level $r$ corresponds
539		to the paper's level $r+1$.
540	\end{lemma}
541	\begin{proof}
542		\leanok
543		\uses{def:cl-func}
544		For the ``if'' direction, conditions 1 and 4 immediately exhibit $L$ as an $\ell$-level CL function. For the ``only if'' direction one constructs the marginals, factor spaces, and linear maps by induction on $\ell$. In the base case $\ell = 1$ take $L_{\le 1} = L$, $V_1 = V$, and $L_1 = L$. For the inductive step, write $L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})$ as in Definition~\ref{def:cl-func} and apply the inductive hypothesis to each $(\ell-1)$-level function $L_{>1,\,v}$, obtaining its marginals, factor spaces, and linear maps over $V_{>1}$. Define $L_{\le 1} = L_1$ with first factor space $V_1$, and for $k \ge 2$ define $L_{\le k}(x) = x^{L_1} + L'_{x^{L_1},\,<k}(x^{V_{>1}})$, with the $k$-th factor space and linear map of $L$ with prefix $u$ given by those of $L_{>1,\,v}$ at index $k-1$ with prefix $w$, where $v = u^{V_1}$ and $w = u^{V_{>1}}$. Conditions 1--4 are then verified directly from the inductive hypothesis: the direct-sum decomposition of $V_{>1}$ extends to $V$ by adjoining $V_1$, and the sum formula for $L_{\le k}$ follows by unfolding the inductive marginals.
545	\end{proof}
546	
547	The marginal functions, factor spaces, and linear maps of a given CL function $L$ need not be unique. For example, the identity function on $V = \F^n$ is a $1$-level CL function, but it can also be viewed as a $k$-level CL function for any $k \in \{2, \dots, n\}$ with an arbitrary partition of $V$ into factor spaces.
548	
549	\begin{lemma}[Concatenation of conditionally linear functions]\label{lem:cl-concat}
550		\lean{MIPStarRE.QPBT.IsCondLinearOn.concat}
551		\leanok
552		\uses{def:cl-func}
553		Let $\ell, k \ge 0$ be integers and let $U = \F^n$, $V = \F^m$ be linear spaces. Suppose $L$ is a $k$-level CL function on $U$ and, for each $u \in L(U)$, $R_u$ is an $\ell$-level CL function on $V$. Then the \emph{concatenation} $T$ of $L$ and $\{R_u\}_u$, defined by
554		\[
555			T(x) = L(x^U) + R_{L(x^U)}(x^V)\,,
556		\]
557		is a $(k+\ell)$-level conditionally linear function on $U \oplus V$.
558	\end{lemma}
559	\begin{proof}
560		\leanok
561		\uses{def:cl-func}
562		By induction on $k$. The case $k = 0$ follows directly from Definition~\ref{def:cl-func}, since then $L = 0$ and $T$ acts by the single $\ell$-level function $R_0$ on the register subspace $V$. For the inductive step, write $L(x^U) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{U_{>1}})$ with complementary register subspaces $U_1$ and $U_{>1}$ of $U$. For each value $x^{L_1}$, the function $T_{>1,\,x^{L_1}}$ on $U_{>1} \oplus V$ sending $x^{U_{>1} \oplus V}$ to $L_{>1,\,x^{L_1}}(x^{U_{>1}}) + R_{x^{L_1} + x^{L_{>1}}}(x^V)$ is the concatenation of the $(k-1)$-level function $L_{>1,\,x^{L_1}}$ with a family drawn from $\{R_u\}$, hence is $(k+\ell-1)$-level by the induction hypothesis. The claim then follows from Definition~\ref{def:cl-func} applied with first subspace $U_1$ and first linear map $L_1$.
563	\end{proof}
